fn sendpage_ok(page: *mut page) -> bool {
PageSlab(page as *const page) == 0 && page_count(page as *const page) >= 1
}

// ld/ldx fields
// double word (64-bit)
// atomic memory ops - op type in immediate
// alu/jmp fields
// mov reg to reg
// atomic op type fields (stored in immediate)
// not an opcode on its own, used to build others
// atomic compare-and-write
// load-acquire
// store-release
#[repr(C)]
#[derive(Clone, Copy)]
struct bpf_insn {
    code: u8,
    __slate_bits_0: __slate_bits::__SlateBits1086U0,
    off: i16,
    imm: i32,
}


// 1 << 13
// insn[0].src_reg:  BPF_PSEUDO_FUNC
// insn[0].imm:      insn offset to the func
// insn[1].imm:      0
// insn[0].off:      0
// insn[1].off:      0
// ldimm64 rewrite:  address of the function
// verifier type:    PTR_TO_FUNC.
#[repr(C)]
#[derive(Clone, Copy)]
